const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

function getDoc() {
  return this.document;
}

function qs(sel) {
  const el = getDoc.call(this).querySelector(sel);
  if (!el) throw new Error(`querySelector("${sel}") returned null`);
  return el;
}

function qsa(sel) {
  return getDoc.call(this).querySelectorAll(sel);
}

function textOf(el) {
  return (el.textContent || '').trim();
}

function findTodoLi(labelText) {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && textOf(label) === labelText) return li;
  }
  return null;
}

function findTodoLabel(labelText) {
  const li = findTodoLi.call(this, labelText);
  return li ? li.querySelector('label') : null;
}

function isVisible(el) {
  if (!el) return false;
  if (el.style && el.style.display === 'none') return false;
  if (el.hidden) return false;
  // Check if the element or ancestor has display none via style
  let cur = el;
  while (cur) {
    if (cur.style && cur.style.display === 'none') return false;
    if (cur.hidden) return false;
    cur = cur.parentElement;
  }
  return true;
}

function isHidden(el) {
  return !isVisible.call(this, el);
}

function todoData() {
  const raw = this.window.localStorage.getItem('todos-vanilla');
  return raw ? JSON.parse(raw) : [];
}

function saveTodoData(todos) {
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
}

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  assert.ok(this.document, 'app should be loaded');
  const main = this.document.querySelector('.todoapp');
  assert.ok(main, 'todoapp section should exist');
});

Given('the todo input is focused', function () {
  const input = qs.call(this, '.new-todo');
  input.focus();
  assert.strictEqual(this.document.activeElement, input, 'todo input should be focused');
});

Given('the todo list is empty', function () {
  const listEl = qs.call(this, '.todo-list');
  listEl.innerHTML = '';
  this.window.localStorage.removeItem('todos-vanilla');
  assert.strictEqual(qsa.call(this, '.todo-list li').length, 0, 'todo list should be empty');
});

Given('the todo list contains {string}', function (title) {
  const list = qs.call(this, '.todo-list');
  const li = this.document.createElement('li');
  li.innerHTML =
    `<div class="view"><input class="toggle" type="checkbox"><label>${title}</label><button class="destroy"></button></div><input class="edit" value="${title}">`;
  list.appendChild(li);
  // Persist to localStorage
  const todos = todoData.call(this);
  todos.push({ id: Date.now() + Math.random(), title, completed: false });
  saveTodoData.call(this, todos);
  // Ensure main and footer are visible
  qs.call(this, '.main').style.display = 'block';
  qs.call(this, '.footer').style.display = 'block';
});

Given('{string} is completed', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  li.classList.add('completed');
  const cb = li.querySelector('.toggle');
  if (cb) cb.checked = true;
  const todos = todoData.call(this);
  for (const t of todos) {
    if (t.title === title) { t.completed = true; break; }
  }
  saveTodoData.call(this, todos);
});

Given('all todos are completed', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    li.classList.add('completed');
    const cb = li.querySelector('.toggle');
    if (cb) cb.checked = true;
  }
  const todos = todoData.call(this);
  for (const t of todos) t.completed = true;
  saveTodoData.call(this, todos);
});

Given('no todos are completed', function () {
  const items = qsa.call(this, '.todo-list li');
  for (const li of items) {
    li.classList.remove('completed');
    const cb = li.querySelector('.toggle');
    if (cb) cb.checked = false;
  }
  const todos = todoData.call(this);
  for (const t of todos) t.completed = false;
  saveTodoData.call(this, todos);
});

Given('the route is {string}', function (route) {
  this.window.location.hash = route;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Given('I navigate to {string}', function (route) {
  this.navigate(route);
});

Given('localStorage contains a todo with title {string} and completed {word}', function (title, completedStr) {
  const completed = completedStr === 'true';
  const todos = todoData.call(this);
  todos.push({ id: Date.now() + Math.random(), title, completed });
  saveTodoData.call(this, todos);
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When('I type {string} into the todo input and press Enter', function (value) {
  const input = qs.call(this, '.new-todo');
  input.value = value;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I click the destroy button on {string}', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  const destroyBtn = li.querySelector('.destroy');
  assert.ok(destroyBtn, 'destroy button should exist');
  destroyBtn.click();
});

When('I double-click the label of {string}', function (title) {
  const label = findTodoLabel.call(this, title);
  assert.ok(label, `label for "${title}" should exist`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the edit input to {string} and press Enter', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I change the edit input to {string} and blur the input', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I change the edit input to {string} and press Escape', function (newValue) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should be visible');
  editInput.value = newValue;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('I view the todo count', function () {
  // The count is always visible in the DOM
});

When('I click the checkbox on {string}', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  const cb = li.querySelector('.toggle');
  assert.ok(cb, 'checkbox should exist');
  cb.click();
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = qs.call(this, '#toggle-all');
  toggleAll.click();
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the clear-completed button', function () {
  const btn = qs.call(this, '.clear-completed');
  btn.click();
});

When('I inspect localStorage', function () {
  // Setup step, no assertion needed
});

When('the app is reloaded', function () {
  this.loadApp();
});

When('the app is reloaded without saving the edit', function () {
  this.loadApp();
});

// ---------------------------------------------------------------------------
// Then steps
// ---------------------------------------------------------------------------

Then('{string} appears in the todo list', function (title) {
  const label = findTodoLabel.call(this, title);
  assert.ok(label, `"${title}" should appear in the todo list`);
});

Then('the todo input is cleared', function () {
  const input = qs.call(this, '.new-todo');
  assert.strictEqual(input.value, '', 'todo input should be cleared');
});

Then('#main and #footer are visible', function () {
  assert.ok(isVisible.call(this, qs.call(this, '.main')), '#main should be visible');
  assert.ok(isVisible.call(this, qs.call(this, '.footer')), '#footer should be visible');
});

Then('no new todo is added to the list', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li').length, 0, 'no todo should be added');
});

Then('#main is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.main')), '#main should be hidden');
});

Then('#footer is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.footer')), '#footer should be hidden');
});

Then('{string} is removed from the todo list', function (title) {
  assert.strictEqual(findTodoLabel.call(this, title), null, `"${title}" should be removed`);
});

Then('{string} is in the todo list', function (title) {
  assert.ok(findTodoLabel.call(this, title), `"${title}" should be in the todo list`);
});

Then('the todo item has the editing class', function () {
  assert.ok(qs.call(this, '.todo-list li.editing'), 'a todo item should have editing class');
});

Then('the edit input is focused', function () {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.ok(editInput, 'edit input should exist');
  assert.strictEqual(this.document.activeElement, editInput, 'edit input should be focused');
});

Then('the edit input contains {string}', function (value) {
  const editInput = qs.call(this, '.todo-list li.editing .edit');
  assert.strictEqual(editInput.value, value, `edit input should contain "${value}"`);
});

Then('{string} is not in the todo list', function (title) {
  assert.strictEqual(findTodoLabel.call(this, title), null, `"${title}" should not be in the todo list`);
});

Then('the editing class is removed', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li.editing').length, 0, 'editing class should be removed');
});

Then('the count shows {string}', function (expected) {
  assert.strictEqual(textOf(qs.call(this, '.todo-count strong')), expected, `count should show ${expected}`);
});

Then('the count label says {string}', function (expected) {
  const text = textOf(qs.call(this, '.todo-count'));
  assert.ok(text.includes(expected), `count label should contain "${expected}", got "${text}"`);
});

Then('{string} has the completed class', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(li.classList.contains('completed'), `"${title}" should have completed class`);
});

Then('{string} does not have the completed class', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(!li.classList.contains('completed'), `"${title}" should not have completed class`);
});

Then('its checkbox is checked', function () {
  const checkeds = qsa.call(this, '.todo-list li .toggle:checked');
  assert.ok(checkeds.length > 0, 'at least one checkbox should be checked');
});

Then('its checkbox is not checked', function () {
  const uncheckeds = qsa.call(this, '.todo-list li .toggle:not(:checked)');
  const checkeds = qsa.call(this, '.todo-list li .toggle:checked');
  assert.ok(uncheckeds.length > 0 || checkeds.length === 0, 'at least one checkbox should not be checked');
});

Then('all todos have the completed class', function () {
  const items = qsa.call(this, '.todo-list li');
  assert.ok(items.length > 0, 'there should be todos');
  for (const li of items) {
    assert.ok(li.classList.contains('completed'), 'all todos should have completed class');
  }
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(qs.call(this, '#toggle-all').checked, 'toggle-all checkbox should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  assert.ok(!qs.call(this, '#toggle-all').checked, 'toggle-all checkbox should not be checked');
});

Then('no todo has the completed class', function () {
  assert.strictEqual(qsa.call(this, '.todo-list li.completed').length, 0, 'no todo should have completed class');
});

Then('the clear-completed button is hidden', function () {
  assert.ok(isHidden.call(this, qs.call(this, '.clear-completed')), 'clear-completed button should be hidden');
});

Then('the clear-completed button is visible', function () {
  assert.ok(isVisible.call(this, qs.call(this, '.clear-completed')), 'clear-completed button should be visible');
});

Then('{string} is saved in localStorage under key {string}', function (title, key) {
  const raw = this.window.localStorage.getItem(key);
  assert.ok(raw, `localStorage key "${key}" should exist`);
  const todos = JSON.parse(raw);
  assert.ok(todos.find(t => t.title === title), `todo "${title}" should be saved in localStorage`);
});

Then('each stored todo has {string}, {string}, and {string} properties', function (prop1, prop2, prop3) {
  const todos = todoData.call(this);
  for (const t of todos) {
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop1), `todo should have "${prop1}" property`);
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop2), `todo should have "${prop2}" property`);
    assert.ok(Object.prototype.hasOwnProperty.call(t, prop3), `todo should have "${prop3}" property`);
  }
});

Then('the stored todo {string} has completed set to true', function (title) {
  const todos = todoData.call(this);
  const found = todos.find(t => t.title === title);
  assert.ok(found, `todo "${title}" should exist in localStorage`);
  assert.strictEqual(found.completed, true, `"${title}" should have completed=true`);
});

Then('the stored todo {string} has title {string}', function (oldTitle, newTitle) {
  const todos = todoData.call(this);
  const found = todos.find(t => t.title === oldTitle);
  assert.ok(found, `todo "${oldTitle}" should exist in localStorage`);
  assert.strictEqual(found.title, newTitle, `title should be "${newTitle}"`);
});

Then('{string} is removed from localStorage', function (title) {
  const todos = todoData.call(this);
  assert.strictEqual(todos.find(t => t.title === title), undefined,
    `"${title}" should be removed from localStorage`);
});

Then('{string} remains in localStorage', function (title) {
  assert.ok(todoData.call(this).find(t => t.title === title),
    `"${title}" should remain in localStorage`);
});

Then('it has the completed class', function () {
  assert.ok(qsa.call(this, '.todo-list li.completed').length > 0, 'a completed todo should exist');
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = findTodoLi.call(this, title);
  assert.ok(li, `todo "${title}" should exist`);
  assert.ok(!li.classList.contains('editing'), `"${title}" should not be in editing mode`);
});

