/**
 * TodoMVC - Vanilla JS implementation
 */

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId() {
    return Date.now() + Math.random();
  }

  // -----------------------------------------------------------------------
  // View helpers
  // -----------------------------------------------------------------------

  var todoApp = document.querySelector('.todoapp');
  var mainEl = todoApp.querySelector('.main');
  var footerEl = todoApp.querySelector('.footer');
  var todoListEl = todoApp.querySelector('.todo-list');
  var newTodoInput = todoApp.querySelector('.new-todo');
  var toggleAllCheckbox = todoApp.querySelector('#toggle-all');
  var todoCountStrong = todoApp.querySelector('.todo-count strong');
  var todoCountEl = todoApp.querySelector('.todo-count');
  var clearCompletedBtn = todoApp.querySelector('.clear-completed');
  var filterLinks = todoApp.querySelectorAll('.filters a');

  // -----------------------------------------------------------------------
  // Router state
  // -----------------------------------------------------------------------

  var currentFilter = 'all';

  function getFilterFromHash() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function setFilterLinkSelected(filter) {
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      a.classList.toggle('selected', a.getAttribute('href') === '#/' + (filter === 'all' ? '' : filter));
    }
  }

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  function filterTodos(todos, filter) {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function render() {
    var todos = loadTodos();
    var filter = currentFilter;
    var filtered = filterTodos(todos, filter);
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    mainEl.style.display = hasTodos ? 'block' : 'none';
    footerEl.style.display = hasTodos ? 'block' : 'none';

    // Clear and rebuild list
    todoListEl.innerHTML = '';
    for (var i = 0; i < filtered.length; i++) {
      var t = filtered[i];
      var li = document.createElement('li');
      if (t.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(t.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(t.title) + '">';

      todoListEl.appendChild(li);
    }

    // Update count
    todoCountStrong.textContent = activeCount;
    todoCountEl.childNodes[1].textContent = activeCount === 1 ? ' item left' : ' items left';

    // Toggle-all state
    toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

    // Clear completed visibility
    var completedCount = todos.length - activeCount;
    clearCompletedBtn.style.display = completedCount > 0 ? 'block' : 'none';

    // Filter link selected state
    setFilterLinkSelected(filter);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // -----------------------------------------------------------------------
  // Actions
  // -----------------------------------------------------------------------

  function addTodo(title) {
    title = title.trim();
    if (title === '') return;
    var todos = loadTodos();
    todos.push({ id: nextId(), title: title, completed: false });
    saveTodos(todos);
    render();
  }

  function deleteTodo(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos.splice(i, 1);
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  function toggleTodo(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  function toggleAll(completed) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = completed;
    }
    saveTodos(todos);
    render();
  }

  function clearCompleted() {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  function updateTodo(oldTitle, newTitle) {
    newTitle = newTitle.trim();
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === oldTitle) {
        if (newTitle === '') {
          todos.splice(i, 1);
        } else {
          todos[i].title = newTitle;
        }
        break;
      }
    }
    saveTodos(todos);
    render();
  }

  function findByTitle(title) {
    var todos = loadTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].title === title) return todos[i];
    }
    return null;
  }

  // -----------------------------------------------------------------------
  // Event handlers
  // -----------------------------------------------------------------------

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  newTodoInput.addEventListener('change', function () {
    // change event for step definitions that trigger it
  });

  todoListEl.addEventListener('change', function (e) {
    var target = e.target;
    if (target.classList.contains('toggle')) {
      var li = target.closest('li');
      var label = li ? li.querySelector('label') : null;
      if (label) {
        toggleTodo(label.textContent.trim());
      }
    }
  });

  todoListEl.addEventListener('click', function (e) {
    var target = e.target;
    if (target.classList.contains('destroy')) {
      var li = target.closest('li');
      var label = li ? li.querySelector('label') : null;
      if (label) {
        deleteTodo(label.textContent.trim());
      }
    }
  });

  todoListEl.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      if (li) {
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.value = target.textContent.trim();
        editInput.focus();
      }
    }
  });

  todoListEl.addEventListener('focusout', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (li && li.classList.contains('editing')) {
        var oldTitle = li.querySelector('label').textContent.trim();
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      }
    }
  });

  todoListEl.addEventListener('blur', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (li && li.classList.contains('editing')) {
        var oldTitle = li.querySelector('label').textContent.trim();
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      }
    }
  }, true);

  todoListEl.addEventListener('keydown', function (e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest('li');
      if (!li) return;
      var oldTitle = li.querySelector('label').textContent.trim();

      if (e.keyCode === ENTER_KEY) {
        var newTitle = target.value.trim();
        if (newTitle === '') {
          deleteTodo(oldTitle);
        } else if (newTitle !== oldTitle) {
          updateTodo(oldTitle, newTitle);
        }
        li.classList.remove('editing');
      } else if (e.keyCode === ESCAPE_KEY) {
        target.value = oldTitle;
        li.classList.remove('editing');
      }
    }
  });

  toggleAllCheckbox.addEventListener('change', function () {
    toggleAll(toggleAllCheckbox.checked);
  });

  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // -----------------------------------------------------------------------
  // Routing
  // -----------------------------------------------------------------------

  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    render();
  });

  // -----------------------------------------------------------------------
  // Init
  // -----------------------------------------------------------------------

  currentFilter = getFilterFromHash();
  render();
})();

